<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVersion\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;

use Throwable;

use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersionAttributes;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersionRef;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersion;
use Civi\Lughauth\Features\Document\TemplateVersion\Application\Service\Visibility\TemplateVersionVisibilityService;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateVersionRetrieveUsecase
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly EventDispatcherInterface $dispatcher,    private readonly TemplateVersionVisibilityService $visibility,
    private readonly TemplateVersionReadGateway $reader
  ) {
  }

  public function allowRetrieve(?TemplateVersionRef $ref = null): Allow
  {
    $this->logDebug("Check allow of retrieve usecase for Template version");
    $span = $this->startSpan("Check allow of retrieve usecase for Template version");
    try {
      $result = $this->dispatcher->dispatch(new TemplateVersionRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
      return $result->getAllow();
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function hiddenFields(?TemplateVersionRef $ref = null): array
  {
    $this->logDebug("Check hidden fields usecase for Template version");
    $span = $this->startSpan("Check hidden fields usecase for Template version");
    try {
      return $this->visibility->fieldsToHide($ref);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function retrieve(string $uid): TemplateVersionRetrieveResult
  {
    $this->logDebug("Run retrieve usecase for Template version");
    $span = $this->startSpan("Run retrieve usecase for Template version");
    try {
      $ref = new TemplateVersionRef($uid);
      $allow = $this->allowRetrieve($ref);
      if( !$allow->allowed ) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve Template version');
      }
      if (!$result = $this->visibility->retrieveVisible($ref)) {
        throw new NotFoundException($uid);
      }
      $output = $this->visibility->copyWithHidden(          $this->visibility->prepareVisibleData( $result ) );
      return new TemplateVersionRetrieveResult($output);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
